import{_ as a,c as e,o as s,a4 as t}from"./chunks/framework.ssOvXUgL.js";const g=JSON.parse('{"title":"内置指令","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/use/built_in.md","filePath":"deploy/use/built_in.md","lastUpdated":1728809929000}'),n={name:"deploy/use/built_in.md"},p=t(`<h1 id="内置指令" tabindex="-1">内置指令 <a class="header-anchor" href="#内置指令" aria-label="Permalink to &quot;内置指令&quot;">​</a></h1><p>严格来讲，所有指令都有插件提供。在 <code>Adachi-BOT</code> 中，内置了三个插件：<code>@help</code>、<code>@management</code>。 它们分别用于提供<strong>使用帮助</strong>、<strong>bot 管理</strong>的功能。</p><p>下面将分别对两个内置插件的指令做出说明（均以默认指令起始符 <code>#</code> 和默认指令名为例）</p><h2 id="help-插件" tabindex="-1">@help 插件 <a class="header-anchor" href="#help-插件" aria-label="Permalink to &quot;@help 插件&quot;">​</a></h2><h3 id="帮助" tabindex="-1">帮助 <a class="header-anchor" href="#帮助" aria-label="Permalink to &quot;帮助&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#help</span></span>
<span class="line"><span>#help -k</span></span></code></pre></div><p>列举当前用户权限允许使用的全部指令，可通过修改 <code>config/directive.yml =&gt; helpMessageStyle</code> 来修改展示效果， 共有<strong>文本</strong>、<strong>转发消息</strong>和<strong>图片</strong>三种展示形式。</p><p>拥有可选参数 <code>-k</code>，可以查看所有指令的 <code>cmdKey</code> 值，供后续指令使用。</p><h3 id="详情" tabindex="-1">详情 <a class="header-anchor" href="#详情" aria-label="Permalink to &quot;详情&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#detail 1</span></span></code></pre></div><p>查看指令的详细信息，这些详细信息由插件开发者提供，若未提供则提示 “该指令暂无更多信息”</p><p>拥有参数 <code>指令序号</code>，填写 <code>help</code> 指令中提供的指令序号。</p><h3 id="联系bot持有者" tabindex="-1">联系bot持有者 <a class="header-anchor" href="#联系bot持有者" aria-label="Permalink to &quot;联系bot持有者&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#call bot出问题啦</span></span></code></pre></div><p>通常由用户使用，可以通过此指令向 bot 主人 qq 发送反馈消息。例如</p><p>默认情况下，每人每天可以使用 <code>3</code> 次，通过 <code>config/directive.yml =&gt; callTimes</code> 修改次数。</p><h2 id="management-插件" tabindex="-1">@management 插件 <a class="header-anchor" href="#management-插件" aria-label="Permalink to &quot;@management 插件&quot;">​</a></h2><h3 id="管理设置" tabindex="-1">管理设置 <a class="header-anchor" href="#管理设置" aria-label="Permalink to &quot;管理设置&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#manager 114514191</span></span>
<span class="line"><span>#unmanaged 114514191</span></span></code></pre></div><p>设置/取消 bot 管理员， 管理员是仅次于 <code>master（bot主人）</code> 的权限身份。</p><p>默认情况下基本所有的管理命令均会对管理员开放，可通过 <code>commands.yml =&gt; 各指令的 auth 属性</code> 来修改这一默认行为。</p><h3 id="封禁用户" tabindex="-1">封禁用户 <a class="header-anchor" href="#封禁用户" aria-label="Permalink to &quot;封禁用户&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ban u114514191</span></span>
<span class="line"><span>#ban g114514191</span></span>
<span class="line"><span>#unban u114514191</span></span>
<span class="line"><span>#unban g114514191</span></span></code></pre></div><p>封禁或解禁用户/群组。被封今后的用户或群组无法再触发任何 bot 指令。</p><p>参数为用户 qq 或群号，当为用户 qq 号时，需要携带标识符 <code>u</code>，反之为 <code>g</code>。</p><h3 id="指令权限" tabindex="-1">指令权限 <a class="header-anchor" href="#指令权限" aria-label="Permalink to &quot;指令权限&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#limit u114514191 adachi.call on</span></span>
<span class="line"><span>#limit u114514191 adachi.call off</span></span>
<span class="line"><span>#limit g114514191 adachi.call on</span></span>
<span class="line"><span>#limit g114514191 adachi.call off</span></span></code></pre></div><p>放行或禁用用户/群组某一指令的使用权限。</p><p>具有三个参数：</p><ul><li>目标用户 qq 或群号，同理使用 <code>u</code> 或 <code>g</code> 标识符区分</li><li>指令的 <code>cmdKey</code>，使用上面的帮助质量 <code>#help -k</code> 查看</li><li>开启或关闭键，on 为放行，off 为禁用</li></ul><h3 id="操作冷却" tabindex="-1">操作冷却 <a class="header-anchor" href="#操作冷却" aria-label="Permalink to &quot;操作冷却&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#int u114514191 3000</span></span>
<span class="line"><span>#int g114514191 3000</span></span></code></pre></div><p>设置目标用户/群组的指令响应间隔时间，在响应间隔时间内尝试触发指令则不会得到响应。</p><p>默认情况下，私聊的响应间隔时间为 2000ms，群聊为 1500ms。 通过配置项 <code>directive.yml =&gt; groupIntervalTime</code> 与 <code>directive.yml =&gt; privateIntervalTime</code> 可以分别设置私聊与群组的响应间隔时间。</p><p>而此指令可以单独针对具体用户/群组具体处理，其优先级高于群组与私聊的响应间隔时间。</p><p>具有两个参数：</p><ul><li>目标用户 qq 或群号，同理使用 <code>u</code> 或 <code>g</code> 标识符区分</li><li>响应间隔时间，单位毫秒</li></ul><h3 id="刷新配置" tabindex="-1">刷新配置 <a class="header-anchor" href="#刷新配置" aria-label="Permalink to &quot;刷新配置&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#refresh</span></span></code></pre></div><p>热重载配置项，无需重启项目即可使对配置项的修改生效。</p><h3 id="更新bot" tabindex="-1">更新bot <a class="header-anchor" href="#更新bot" aria-label="Permalink to &quot;更新bot&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#upgrade</span></span>
<span class="line"><span>#upgrede -f</span></span></code></pre></div><p>热更新 bot 源码，代替用户执行 <code>git pull</code> 操作。</p><p>具有可选参数 <code>-f</code>，默认情况下遇到代码冲突问题时，更新将会失败。携带 <code>-f</code> 则会强制覆盖更新，慎重使用。</p><blockquote><p>该指令仅支持 pm2 与 docker 模式启动的 bot，<code>pnpm start</code> 方式启动的 bot 执行将会报错。</p></blockquote><h3 id="重启bot" tabindex="-1">重启bot <a class="header-anchor" href="#重启bot" aria-label="Permalink to &quot;重启bot&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#restart</span></span></code></pre></div><p>重启 bot。</p><blockquote><p>该指令仅支持 pm2 与 docker 模式启动的 bot，<code>pnpm start</code> 方式启动的 bot 执行将会报错。</p></blockquote><h3 id="重载插件" tabindex="-1">重载插件 <a class="header-anchor" href="#重载插件" aria-label="Permalink to &quot;重载插件&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#reload</span></span>
<span class="line"><span>#reload music</span></span></code></pre></div><p>重载插件源码。默认情况下对全部插件进行重载。</p><p>具有可选参数，用于指定具体重载的插件名称，携带参数后不再重载全部插件。</p><h3 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to &quot;更新插件&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#upgrade_plugins</span></span>
<span class="line"><span>#upgrade_plugins music</span></span>
<span class="line"><span>#upgrade_plugins -f music</span></span>
<span class="line"><span>#upgrade_plugins -s music</span></span>
<span class="line"><span>#upgrade_plugins -f -s music</span></span></code></pre></div><p>检查并热更新插件源码。默认情况下对全部插件进行热更新，并重载更新成功的插件。</p><p>具有三个参数：</p><ul><li>-f，可选，覆盖本地修改强制更新</li><li>-s，可选，不会自动重载更新成功的插件</li><li>指定具体更新的插件名称，携带参数后不再尝试更新全部插件。</li></ul>`,58),i=[p];function l(o,c,d,h,r,u){return s(),e("div",null,i)}const m=a(n,[["render",l]]);export{g as __pageData,m as default};
